package com.zenbyte.leave.controller;
import com.zenbyte.leave.entity.AppUser; import com.zenbyte.leave.service.*; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/user") public class UserSelfController {private final AuthenticationService auth;private final EmployeeService es;private final LeaveCalculationService calc;public UserSelfController(AuthenticationService auth,EmployeeService es,LeaveCalculationService calc){this.auth=auth;this.es=es;this.calc=calc;} @GetMapping("/profile") public Object profile(){AppUser u=auth.current();return es.get(u.getEmployee().getId());} @GetMapping("/leave-days") public Map<String,Object> days(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to){return Map.of("days",calc.countWorkingDays(from,to));}}
